@Tags(['slow'])
library;

import 'dart:async';
import 'dart:math';

import 'package:harbor/harbor.dart';
import 'package:rohd/rohd.dart';
import 'package:test/test.dart';

// Full intra predictor: availability + runtime angle_delta, all 13 modes, vs
// predictIntraRaw (no edge filter, above-right/below-left repeat). Goldens
// captured from the reference predictIntraRaw are embedded at the end.
void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  for (final bs in [4, 8]) {
    test(
      'HarborIntraPredFull bs=$bs matches predictIntraRaw (avail+angle)',
      () async {
        final t = HarborIntraPredFull(bs: bs);
        final clk = SimpleClockGenerator(10).clk;
        final mode = Logic(name: 'mode', width: 4);
        final ad = Logic(name: 'angle_delta', width: 4);
        final haveA = Logic(name: 'have_above');
        final haveL = Logic(name: 'have_left');
        final above = Logic(name: 'above', width: bs * 8);
        final left = Logic(name: 'left', width: bs * 8);
        final corner = Logic(name: 'corner', width: 8);
        t.input('mode').srcConnection! <= mode;
        t.input('angle_delta').srcConnection! <= ad;
        t.input('have_above').srcConnection! <= haveA;
        t.input('have_left').srcConnection! <= haveL;
        t.input('above').srcConnection! <= above;
        t.input('left').srcConnection! <= left;
        t.input('corner').srcConnection! <= corner;
        await t.build();
        Simulator.setMaxSimTime(40000000);
        unawaited(Simulator.run());

        BigInt packB(List<int> b) {
          var v = BigInt.zero;
          for (var i = 0; i < b.length; i++) {
            v |= BigInt.from(b[i] & 0xff) << (i * 8);
          }
          return v;
        }

        final golden = bs == 4 ? _goldenFull4 : _goldenFull8;
        var gi = 0;
        final rng = Random(0xF011 + bs);
        for (var iter = 0; iter < 12; iter++) {
          final aSrc = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
          final lSrc = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
          final cr = rng.nextInt(256);
          for (var m = 0; m < 13; m++) {
            final isDir = m >= 1 && m <= 8;
            final deltas = isDir ? [-3, -1, 0, 2, 3] : [0];
            for (final d in deltas) {
              for (var av0 = 0; av0 < 2; av0++) {
                for (var lv0 = 0; lv0 < 2; lv0++) {
                  mode.put(m);
                  ad.put(d & 0xF);
                  haveA.put(av0);
                  haveL.put(lv0);
                  above.put(packB(aSrc));
                  left.put(packB(lSrc));
                  corner.put(cr);
                  await clk.nextPosedge;

                  final want = golden.sublist(gi * bs * bs, (gi + 1) * bs * bs);
                  gi++;
                  final pv = t.output('pred').value.toBigInt();
                  final got = [
                    for (var p = 0; p < bs * bs; p++)
                      ((pv >> (p * 8)) & BigInt.from(0xff)).toInt(),
                  ];
                  expect(
                    got,
                    equals(want),
                    reason: 'bs=$bs m=$m d=$d a=$av0 l=$lv0 iter=$iter',
                  );
                }
              }
            }
          }
        }
        await Simulator.endSimulation();
      },
    );
  }
}

